    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address newOwner) public payable {
        require(newOwner != address(0));

        address originalOwner = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balanceBefore = address(c).balance;

        bool reverted;
        bool success = c.setOwner(newOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            assert(c.owner() == originalOwner);
            assert(address(c).balance == balanceBefore);
        } else {
            reverted = false;
            assert(success == true);
            assert(c.owner() == newOwner);
            assert(address(c).balance == balanceBefore);
        }

        assert(reverted || c.owner() == newOwner);
    }

    receive() external payable {}
