pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address newOwner) internal {
        vm.assume(newOwner != address(0));
        address originalOwner;
        try c.owner() returns (address __r) { originalOwner = __r; } catch { return; }
        uint256 balanceBefore = address(c).balance;
        bool reverted;
        try c.setOwner(newOwner) returns (bool success) {
            reverted = false;
            assert(success == true);
            assert(c.owner() == newOwner);
            assert(address(c).balance == balanceBefore);
        } catch {
            reverted = true;
            assert(c.owner() == originalOwner);
            assert(address(c).balance == balanceBefore);
        }
        assertTrue(reverted || c.owner() == newOwner);
    }

    function testFuzz_run(address newOwner) public {
        vm.assume(newOwner.code.length == 0 && uint160(newOwner) > 0xffff && newOwner != address(this) && newOwner != address(c) && newOwner != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && newOwner != 0x000000000000000000636F6e736F6c652e6c6f67 && newOwner != 0x4e59b44847b379578588920cA78FbF26c0B4956C && newOwner != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(newOwner);
    }

    receive() external payable {}
}
